// Verify the final provider payload without sending a model request or executing any UI tool.
import { writeFileSync } from 'node:fs';
export default function inspect(pi) {
    pi.on('before_provider_request', (event, ctx) => {
        const js = pi.getAllTools().find((tool) => tool.name === 'mcp__cua_repl__js');
        const encoded = JSON.stringify(event.payload);
        const report = {
            registeredDescriptionUnchanged: Boolean(js?.description?.startsWith('Control native apps or browsers')),
            originalDesktopExampleStillPresent: Boolean(js?.description?.includes('cua.createBrowserTab("iab"')),
            registeredGuidelines: js?.promptGuidelines ?? [],
            systemPromptHasChromeRestriction: ctx.getSystemPrompt().includes('only these enabled backends: chrome'),
            providerPayloadHasHostGuidance: encoded.includes('pi host guidance:'),
            providerPayloadHasChromeRestriction: encoded.includes('only these enabled backends: chrome'),
            providerPayloadHasRuntimeInstructions: encoded.includes('Codex runtime instructions:'),
            customPromptPreserved: ctx.getSystemPrompt().includes('CUA_CUSTOM_PROMPT_SENTINEL'),
        };
        writeFileSync(process.env.CUA_GUIDANCE_REPORT, JSON.stringify(report, null, 2));
        ctx.abort();
    });
    // A second barrier if a provider ignores the aborted signal: never execute tools in this probe.
    pi.on('tool_call', () => ({block: true, reason: 'Read-only guidance inspection', terminate: true}));
}

// Live verification scope: only create the approved Chrome tab, read its AX state, and close it.
import { writeFileSync } from 'node:fs';
export default function scope(pi) {
    const report = { selectedCodes: [], blocked: [], results: [] };
    const save = () => writeFileSync('/tmp/pi-cua-improvements/live.json', JSON.stringify(report, null, 2));
    let stage = 0;
    pi.on('tool_call', (event) => {
        const code = event.input?.code;
        let allowed = false;
        if (event.toolName === 'mcp__cua_repl__js' && typeof code === 'string') {
            if (stage === 0)
                allowed = /^\s*(?:let|var|const)\s+verificationTab\s*=\s*await\s+cua\.createBrowserTab\(\s*(["'])chrome\1\s*,\s*(["'])https:\/\/example\.com\/?\2\s*,\s*\{\s*sessionName:\s*(["'])[^"']*\3\s*,?\s*\}\s*\)\s*;?\s*$/.test(code);
            else if (stage === 1)
                allowed = /^\s*await\s+verificationTab\.getAXState\(\s*\)\s*;?\s*$/.test(code);
            else if (stage === 2)
                allowed = /^\s*await\s+verificationTab\.close\(\s*\)\s*;?\s*$/.test(code);
        }
        if (!allowed) {
            report.blocked.push({ tool: event.toolName, code }); save();
            return {block: true, reason: 'This verification allows only the approved create/read/close sequence.', terminate: true};
        }
        report.selectedCodes.push(code); stage += 1; save();
    });
    pi.on('tool_execution_end', (event) => {
        report.results.push({ tool: event.toolName, isError: event.isError, hasExampleDomain: JSON.stringify(event.result?.content).includes('Example Domain') }); save();
    });
}

// Drives pi in RPC mode through a scripted set of confirmation answers.
//   ANSWERS='Allow,Allow,Allow for this session,none' node confirm-driver.mjs <pi-binary> <pi args...> -- <prompt>
// Answer tokens: "Allow", "Allow for this session", "Always allow", "Deny", "Cancel", "delay:<ms>:<answer>",
// "abort" (send RPC abort while the dialog is open, like Esc), "dismiss" (cancelled: true).
import { spawn } from "node:child_process";

const argv = process.argv.slice(2);
const separator = argv.indexOf("--");
const [piBinary, ...piArgs] = argv.slice(0, separator);
const prompt = argv.slice(separator + 1).join(" ");
const answers = (process.env.ANSWERS ?? "").split(",").map((a) => a.trim()).filter(Boolean);
let answerIndex = 0;
const child = spawn(piBinary, piArgs, { stdio: ["pipe", "pipe", "pipe"] });
child.stderr.on("data", (chunk) => {
    const text = chunk.toString();
    if (!text.startsWith("Warning: No models")) process.stdout.write(`[stderr] ${text}`);
});
const send = (record) => {
    console.log(`>>> ${JSON.stringify(record).slice(0, 220)}`);
    child.stdin.write(`${JSON.stringify(record)}\n`);
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const t0 = Date.now();
const stamp = () => `+${((Date.now() - t0) / 1000).toFixed(1)}s`;
const handleSelect = async (record) => {
    const token = answers[answerIndex] ?? "Cancel";
    answerIndex += 1;
    console.log(`<<< ${stamp()} select #${answerIndex} title=${JSON.stringify(record.title)} options=${JSON.stringify(record.options)} → ${token}`);
    let answer = token;
    if (token.startsWith("delay:")) {
        const [, ms, real] = token.split(":");
        console.log(`    waiting ${ms} ms before answering ${real}`);
        await sleep(Number(ms));
        answer = real;
    }
    if (answer === "abort") {
        send({ type: "abort" });
        return;
    }
    if (answer === "dismiss") {
        send({ type: "extension_ui_response", id: record.id, cancelled: true });
        return;
    }
    const match = record.options.find((option) => option.startsWith(`${answer} —`) || option === answer);
    if (!match) {
        console.log(`    no option matches ${answer}; dismissing`);
        send({ type: "extension_ui_response", id: record.id, cancelled: true });
        return;
    }
    send({ type: "extension_ui_response", id: record.id, value: match });
};
let buffer = "";
child.stdout.on("data", (chunk) => {
    buffer += chunk.toString();
    let nl = buffer.indexOf("\n");
    while (nl !== -1) {
        const line = buffer.slice(0, nl).trim();
        buffer = buffer.slice(nl + 1);
        nl = buffer.indexOf("\n");
        if (!line) continue;
        let record;
        try {
            record = JSON.parse(line);
        } catch {
            console.log(`<<< (raw) ${line.slice(0, 200)}`);
            continue;
        }
        if (record.type === "extension_ui_request") {
            if (record.method === "select") void handleSelect(record);
            else if (record.method === "notify") console.log(`<<< ${stamp()} notify ${JSON.stringify(record.message).slice(0, 200)}`);
            else if (record.method === "confirm" || record.method === "input") {
                console.log(`<<< ${stamp()} ${record.method} ${JSON.stringify(record.title).slice(0, 200)} → dismiss`);
                send({ type: "extension_ui_response", id: record.id, cancelled: true });
            }
            continue;
        }
        if (record.type === "response") {
            console.log(`<<< ${stamp()} response ${JSON.stringify(record).slice(0, 160)}`);
            continue;
        }
        if (record.type === "tool_execution_start") console.log(`<<< ${stamp()} tool start ${record.toolName} ${JSON.stringify(record.args?.code ?? "").slice(0, 120)}`);
        else if (record.type === "tool_execution_end") console.log(`<<< ${stamp()} tool end isError=${record.isError} ${JSON.stringify(record.result?.content?.map((b) => (b.type === "text" ? b.text.slice(0, 160) : b.type)) ?? "")}`);
        else if (record.type === "agent_end") {
            console.log(`<<< ${stamp()} agent_end`);
            setTimeout(() => child.kill("SIGTERM"), Number(process.env.LINGER_MS ?? 3000));
        } else if (record.type === "message_end" && record.message?.role === "assistant") {
            const text = (record.message.content ?? []).filter((c) => c.type === "text").map((c) => c.text).join(" ");
            if (text) console.log(`<<< ${stamp()} assistant: ${text.slice(0, 400)}`);
        }
    }
});
child.on("exit", (code, signal) => console.log(`pi exited code=${code} signal=${signal}`));
setTimeout(() => send({ id: "p1", type: "prompt", message: prompt }), 1500);
setTimeout(() => {
    console.log("timeout: killing pi");
    child.kill("SIGKILL");
}, Number(process.env.MAX_MS ?? 400_000)).unref();
